let managedTeamId=0,teamManagementBusy=false;
function managementAlignment(teams){return teams.map(t=>({id:t.id,key:t.key,conference:t.conference,divisionId:t.divisionId}))}
function readScheduleAlignment(raw,teams,bad){if(raw===undefined)return undefined;if(!Array.isArray(raw)||raw.length!==teams.length||raw.some((t,i)=>t.id!==i||typeof t.conference!=='string'||t.conference.length>35||typeof t.divisionId!=='string'||t.divisionId.length>80)||!nbaAlignment(raw.map((t,i)=>({...t,key:teams[i].key}))))bad('invalid schedule alignment');return raw.map((t,i)=>({id:t.id,key:teams[i].key,conference:t.conference,divisionId:t.divisionId}))}
function chooseManagedTeam(id){if(teamManagementBusy)return;managedTeamId=Number(id);render()}
function teamManagementView(){const t=state.teams[managedTeamId]||team(),logos=logoChoices(),logo=logos.findIndex(l=>l.logoAtlas===t.logoAtlas&&l.logoIndex===t.logoIndex);managedTeamId=t.id;
 return `<section class="panel team-management"><div class="panelhead"><h2>Team directory</h2><label class="tm-selector">Team<select aria-label="Select team to edit" onchange="chooseManagedTeam(this.value)">${state.teams.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${escapeHTML(x.city+' '+x.name)}</option>`).join('')}</select></label></div><div class="tm-body"><div class="tm-identity">${teamLogo(t,true)}<div><div class="eyebrow">${escapeHTML(t.conference)} · ${escapeHTML(t.division)}</div><h2>${escapeHTML(t.city+' '+t.name)}</h2><p>${t.w}–${t.l} · ${t.roster.length} players · ${escapeHTML(t.marketSize)} market</p></div></div><form onsubmit="saveManagedTeam(event,${t.id})">${relocationPresetFields(t)}<div class="tm-grid"><label>City<input name="city" onchange="this.form.elements.arenaCity.value='';this.form.elements.elevationFt.value=''" value="${escapeHTML(t.city)}" maxlength="35" required></label><label>Team name<input name="name" value="${escapeHTML(t.name)}" maxlength="35" required></label><label>Abbreviation<input name="abbr" value="${escapeHTML(t.abbr)}" pattern="[A-Za-z0-9]{2,5}" maxlength="5" required></label><label>Arena name<input name="arenaName" value="${escapeHTML(teamArena(t))}" maxlength="80" required></label><label>Stadium capacity<input name="stadiumCapacity" type="number" min="1" max="100000" step="1" value="${teamStadiumCapacity(t)}" required><small>Total seats · Applies to future games.</small></label>${altitudeEditorFields(t)}<label>Market size<select name="marketSize">${['Small','Medium','Large'].map(x=>`<option ${x===t.marketSize?'selected':''}>${x}</option>`).join('')}</select></label><label>Default primary logo<select name="logo">${logos.map((l,i)=>`<option value="${i}" ${i===logo?'selected':''}>${escapeHTML(l.city+' '+l.name)}</option>`).join('')}</select></label>${state.scheduleFormat==='nba82'?`<label>Conference / division exchange<select name="swap"><option value="">Keep current alignment</option>${state.teams.filter(x=>x.divisionId!==t.divisionId).map(x=>`<option value="${x.id}">${escapeHTML(x.city+' '+x.name+' · '+x.conference+' / '+x.division)}</option>`).join('')}</select></label>`:`<label>Division / conference<select name="divisionId">${divisionOptions(t.divisionId||'@'+t.conferenceId,state)}</select></label>`}</div>${managementLogoFields(t)}<h3>Team colors</h3><div class="tm-colors">${t.colors.map((c,i)=>`<label>${['Primary','Secondary','Tertiary'][i]}<div><input type="color" name="color${i}" aria-label="${c.role} color" value="${c.hex}"><input name="colorName${i}" aria-label="${c.role} color name" value="${escapeHTML(c.name)}" maxlength="35" required></div></label>`).join('')}</div><p class="muted">Colors update team accents. Logo artwork keeps its original palette.</p>${state.scheduleFormat==='nba82'?'<p class="muted">Exchanging divisions with another team keeps five teams per division. Standings update immediately; scheduled games stay in place and the next season uses the new alignment.</p>':''}<div class="tm-actions"><button type="button" onclick="render()" ${teamManagementBusy?'disabled':''}>Reset changes</button><button class="primary" type="submit" ${teamManagementBusy?'disabled':''}>${teamManagementBusy?'Saving…':'Save team info'}</button></div><p class="muted" role="status" id="tm-error"></p></form></div></section>`;
}
function applyManagedTeam(id,v){const t=state.teams[id];if(!t)throw Error('Choose a team.');const city=String(v.city||'').trim(),name=String(v.name||'').trim(),abbr=String(v.abbr||'').trim().toUpperCase(),logo=logoChoices()[Number(v.logo)];if(!city||!name||city.length>35||name.length>35||!/^[A-Z0-9]{2,5}$/.test(abbr))throw Error('Enter a city, team name, and 2–5 character abbreviation.');if(state.teams.some(x=>x.id!==id&&x.abbr.toUpperCase()===abbr))throw Error('That abbreviation belongs to another team.');if(!logo||!['Small','Medium','Large'].includes(v.marketSize))throw Error('Choose a valid logo and market size.');const colors=[0,1,2].map(i=>{const role=['Primary','Secondary','Tertiary'][i],hex=String(v['color'+i]||'').toUpperCase(),name=String(v['colorName'+i]||'').trim();if(!/^#[0-9A-F]{6}$/.test(hex)||!name||name.length>35)throw Error('Enter valid team colors and color names.');return {role,hex,name}});
 let swap=null,division=null;if(state.scheduleFormat==='nba82'){if(v.swap!==undefined&&v.swap!==''){swap=state.teams[Number(v.swap)];if(!swap||swap.id===id||swap.divisionId===t.divisionId)throw Error('Choose a team in another division.')}}else{division=state.divisions.find(d=>d.id===v.divisionId);if(!division){const conf=state.conferences.find(c=>'@'+c.id===v.divisionId);if(!conf)throw Error('Choose a division or conference.');division={id:'',name:'',conferenceId:conf.id}}}
 const branding=readTeamBrand({...altitudeEditedTeam(t,v),...(v.stadiumCapacity!==undefined?{stadiumCapacity:Number(v.stadiumCapacity)}:{}),...(v.arenaName!==undefined?{arenaName:v.arenaName}:{}),...(v.secondaryLogoIndex!==undefined?{secondaryLogoIndex:Number(v.secondaryLogoIndex)}:{})},message=>{throw Error(message)});
 const old=t.abbr;if(swap){state.scheduleAlignment??=managementAlignment(state.teams);const keys=['divisionId','division','conference'],before=Object.fromEntries(keys.map(k=>[k,t[k]]));keys.forEach(k=>{t[k]=swap[k];swap[k]=before[k]})}else if(division){if(state.scheduleFormat==='custom')state.customScheduleAlignment??=managementAlignment(state.teams);t.conferenceId=division.conferenceId;t.divisionId=division.id;t.division=division.name;t.conference=state.conferences.find(c=>c.id===division.conferenceId).name}
 Object.assign(t,{...branding,city,name,abbr,marketSize:v.marketSize,colors,color:colors[0].hex,logoAtlas:logo.logoAtlas,logoIndex:logo.logoIndex});
 // Existing box scores and archived player-team splits use abbreviations as join keys.
 if(old!==abbr){for(const h of state.history)for(const p of h.box)if(p.team===old)p.team=abbr;for(const key of ['statsArchive','playerPostseasonArchive'])for(const r of state[key]||[])if(typeof r.team==='string')r.team=r.team.split(' / ').map(a=>a===old?abbr:a).join(' / ')}
 return t;
}
async function saveManagedTeam(event,id){event.preventDefault();if(teamManagementBusy||!ownerCanManage())return;const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),before=copy(state);teamManagementBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{const primary=await readLogoUpload(values.primaryUpload),secondary=await readLogoUpload(values.secondaryUpload);const t=applyManagedTeam(id,values);for(const [kind,data] of [['primary',primary],['secondary',secondary]]){if(values[kind+'Reset'])delete t[kind+'Logo'];if(data)t[kind+'Logo']=data}if(await save()===false){state=before;throw Error('Could not save team changes. Please try again.')}teamManagementBusy=false;render();toast('Team information saved.')}catch(error){state=before;teamManagementBusy=false;render();const node=document.getElementById('tm-error');if(node)node.textContent=error.message;toast(error.message)}}


function teamArena(t){return t.arenaName||t.city+' Arena'}
function validTeamLogo(value){return typeof value==='string'&&value.length<=600000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(value)}
function readTeamBrand(t,bad){const result={};if(t.stadiumCapacity!==undefined){if(!Number.isInteger(t.stadiumCapacity)||t.stadiumCapacity<1||t.stadiumCapacity>100000)bad('Stadium capacity must be a whole number from 1 to 100,000.');result.stadiumCapacity=t.stadiumCapacity;}if(t.arenaName!==undefined){if(typeof t.arenaName!=='string'||!t.arenaName.trim()||t.arenaName.length>80)bad('invalid arena name');result.arenaName=t.arenaName.trim()}for(const key of ['primaryLogo','secondaryLogo'])if(t[key]){if(!validTeamLogo(t[key]))bad('invalid team logo image');result[key]=t[key]}if(t.secondaryLogoIndex!==undefined){if(!Number.isInteger(t.secondaryLogoIndex)||t.secondaryLogoIndex<0||t.secondaryLogoIndex>=SECONDARY_TEAM_KEYS.length)bad('invalid secondary logo');result.secondaryLogoIndex=t.secondaryLogoIndex}return result}
function managementLogoFields(t){return `<h3>Team logos</h3><div class="tm-logo-grid">${['primary','secondary'].map(kind=>`<section class="tm-logo-editor"><h4>${kind==='primary'?'Primary':'Secondary'} logo</h4><div class="tm-logo-preview" id="tm-${kind}-preview">${kind==='primary'?teamLogo(t,true):secondaryTeamLogo(t)}</div>${kind==='secondary'?`<label>Default secondary logo<select name="secondaryLogoIndex">${logoChoices().map((l,i)=>`<option value="${i}" ${i===(t.secondaryLogoIndex??defaultSecondaryLogoIndex(t))?'selected':''}>${escapeHTML(l.city+' '+l.name)}</option>`).join('')}</select></label>`:''}<label>Upload ${kind} logo<input type="file" name="${kind}Upload" accept="image/png,image/jpeg,image/webp" onchange="previewManagedLogo(this,'${kind}')"></label><label class="tm-logo-reset"><input type="checkbox" name="${kind}Reset"> Use default artwork instead of saved upload</label></section>`).join('')}</div><p class="muted">PNG, JPEG or WebP, up to 5 MB each. Transparent PNG works best. Uploads are resized and saved with this career; a new upload takes priority over reset.</p>`}
function previewManagedLogo(input,kind){const file=input.files?.[0];if(!file)return;const node=document.getElementById('tm-'+kind+'-preview');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){input.value='';toast('Choose a PNG, JPEG or WebP image under 5 MB.');return}const img=document.createElement('img'),url=URL.createObjectURL(file);img.alt=kind+' logo preview';img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>{URL.revokeObjectURL(url);input.value='';toast('That image could not be opened.')};img.src=url;node.replaceChildren(img)}
async function readLogoUpload(file){if(!file||!file.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a PNG, JPEG or WebP image under 5 MB.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,256/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/png');if(!validTeamLogo(data))throw Error('Logo image is too large. Choose a smaller image.');return data}finally{bitmap.close()}}

function teamStadiumCapacity(t){return t.stadiumCapacity??(18000+(state.finances?.[t.id]?.level||0)*1000)}

// Relocation reuses this editor: a preset only fills the form. Saving keeps the
// team id, key, roster, contracts, finances and history; abbreviation changes
// re-key archived box scores as for any manual rename.
function relocationPresetFields(t){return `<div class="tm-relocate"><label>Relocate or rebrand from a preset<select name="relocationPreset" aria-describedby="tm-relocate-note"><option value="">Choose a franchise preset</option>${FRANCHISE_PRESETS.map(p=>{const owner=state.teams.find(x=>x.id!==t.id&&x.abbr===p.abbr);return `<option value="${p.abbr}" ${owner?'disabled':''}>${escapeHTML(p.city+' '+p.name)}${owner?' · abbreviation in use':''}</option>`}).join('')}</select></label><button type="button" onclick="applyRelocationPreset(this.form)">Load preset into form</button><p class="muted" id="tm-relocate-note">Fills city, name, abbreviation, arena, capacity, market, colors and logos. Roster, contracts, finances and franchise history stay with this team. Review, then save.</p></div>`}
function applyRelocationPreset(form){const p=franchisePreset(form?.elements.relocationPreset.value);if(!p)return toast('Choose a franchise preset.');const def=presetTeamDefinition(p),f=form.elements,set=(k,v)=>{if(f[k])f[k].value=v},index=PRESET_LOGO_OFFSET+FRANCHISE_PRESETS.indexOf(p);
 set('city',p.city);set('name',p.name);set('abbr',p.abbr);set('arenaName',p.arenaName);set('stadiumCapacity',p.capacity);set('marketSize',p.marketSize);set('logo',index);set('secondaryLogoIndex',index);set('arenaCity','');set('elevationFt','');
 def.colors.forEach((c,i)=>{set('color'+i,c.hex.toLowerCase());set('colorName'+i,c.name)});
 for(const kind of ['primary','secondary'])if(f[kind+'Reset'])f[kind+'Reset'].checked=true;
 const preview=document.getElementById('tm-primary-preview');if(preview)preview.innerHTML=presetLogo(p,true);
 toast(p.city+' '+p.name+' loaded. Save team info to complete the move.')}
